# area: typeddict
# hypothesis: assigning to a ReadOnly key is rejected, reading a NotRequired key needs an 'in' guard, and Unpack[TypedDict] kwargs reject unknown keys and wrong value types; a Literal parameter rejects values outside its set.
from typing import Literal, NotRequired, ReadOnly, TypedDict, Unpack, reveal_type


class Movie(TypedDict):
    title: ReadOnly[str]
    year: NotRequired[int]


class Options(TypedDict, total=False):
    verbose: bool
    level: int


def configure(**kwargs: Unpack[Options]) -> str:
    reveal_type(kwargs)
    return 'configured ' + str(sorted(kwargs))


def describe(m: Movie) -> str:
    if 'year' in m:
        reveal_type(m['year'])
        return m['title'] + ' ' + str(m['year'])
    return m['title']


def retitle(m: Movie) -> None:
    m['title'] = 'Down'  # expect-error: ReadOnly key


def label(kind: Literal['short', 'long']) -> str:
    return kind[:1]


m: Movie = {'title': 'Up'}
retitle(m)
print(describe(m))
print(configure(verbose=True))
print(configure(level='high'))  # expect-error: wrong value type
print(configure(color=1))  # expect-error: unknown key
print(label('long'), label('medium'))  # expect-error: literal not in set
